def solve(**kwargs):
    jobs = kwargs.get('jobs', [])
    n = len(jobs)
    if n == 0:
        return {'schedule': []}
    h = kwargs.get('h', 0.6)
    P = sum(p for p, a, b in jobs)
    d = int(P * h)
    if n > 20:
        # heuristic for large n
        sorted_jobs = sorted(range(n), key=lambda i: jobs[i][1] / jobs[i][0] if jobs[i][0] > 0 else float('inf'))
        schedule = [i + 1 for i in sorted_jobs]
        return {'schedule': schedule}
    INF = float('inf')
    N = 1 << n
    s = [0] * N
    for mask in range(N):
        temp = mask
        for j in range(n):
            if temp & 1:
                s[mask] += jobs[j][0]
            temp >>= 1
    dp = [INF] * N
    dp[0] = 0
    prev = [-1] * N
    for mask in range(N):
        if dp[mask] == INF:
            continue
        cur_sum = s[mask]
        for j in range(n):
            if (mask & (1 << j)) == 0:
                p, a, b = jobs[j]
                C = cur_sum + p
                if C < d:
                    add = a * (d - C)
                elif C > d:
                    add = b * (C - d)
                else:
                    add = 0
                new_dp = dp[mask] + add
                new_mask = mask | (1 << j)
                if new_dp < dp[new_mask]:
                    dp[new_mask] = new_dp
                    prev[new_mask] = j
    full = N - 1
    schedule = []
    mask = full
    while mask:
        j = prev[mask]
        schedule.append(j + 1)
        mask ^= (1 << j)
    schedule.reverse()
    return {'schedule': schedule}
