def solve(**kwargs):
    m = kwargs["m"]
    n = kwargs["n"]
    warehouses = kwargs["warehouses"]
    customers = kwargs["customers"]
    if n == 0:
        return {
            "total_cost": 0.0,
            "warehouse_open": [0] * m,
            "assignments": []
        }
    best_total = float('inf')
    best_open = None
    best_assign = None
    for r in range(m + 1):
        for S in itertools.combinations(range(m), r):
            open_mask = [0] * m
            for j in S:
                open_mask[j] = 1
            fixed = sum(warehouses[j]['fixed_cost'] for j in S)
            remaining_cap = [warehouses[j]['capacity'] for j in S]
            assign = [[0.0] * m for _ in range(n)]
            total_var = 0.0
            open_ws = [j for j in S]
            feasible = True
            for i in range(n):
                dem = customers[i]['demand']
                cst = customers[i]['costs']
                ws_sorted = sorted(open_ws, key=lambda j: cst[j])
                for j in ws_sorted:
                    if remaining_cap[j] > 0:
                        can_assign = min(dem, remaining_cap[j])
                        assign[i][j] = can_assign
                        remaining_cap[j] -= can_assign
                        dem -= can_assign
                        total_var += can_assign * cst[j]
                        if dem <= 0:
                            break
                if dem > 0:
                    feasible = False
                    break
            if feasible:
                total = total_var + fixed
                if total < best_total:
                    best_total = total
                    best_open = open_mask[:]
                    best_assign = [row[:] for row in assign]
    if best_total == float('inf'):
        return {
            "total_cost": 0.0,
            "warehouse_open": [0] * m,
            "assignments": [[0.0] * m for _ in range(n)]
        }
    return {
        "total_cost": best_total,
        "warehouse_open": best_open,
        "assignments": best_assign
    }
